Laboratorio: ¿qué va en Git?


Laboratorio · se ejecuta en tu navegador

Marca qué tiene tu proyecto y el laboratorio genera un .gitignore con explicaciones.

casilla = window.Lab.casilla
viewof g_py = casilla("Código de Python", {value: true})
viewof g_r = casilla("Código de R", {value: true})
viewof g_env = casilla("Claves de API o contraseñas en un archivo .env", {value: true})
viewof g_pers = casilla("Datos con información personal", {value: false})
viewof g_big = casilla("Archivos de datos muy grandes (más de 50 MB)", {value: false})
viewof g_quarto = casilla("Documentos de Quarto", {value: true})



















































{
  const b = [];
  b.push(["# Sistema y editores", ".DS_Store\nThumbs.db\n.vscode/\n.idea/"]);
  if (g_py) b.push(["# Python: entornos y cachés (se regeneran)", ".venv/\n__pycache__/\n*.pyc\n.ipynb_checkpoints/"]);
  if (g_r) b.push(["# R: historial y cachés de renv (renv.lock sí se versiona)", ".Rhistory\n.RData\n.Rproj.user/\nrenv/library/"]);
  if (g_env) b.push(["# Secretos: NUNCA en Git", ".env\n*.key\nsecrets.*"]);
  if (g_pers) b.push(["# Datos personales: fuera del repositorio (y del ordenador si no están protegidos)", "datos/brutos/personales/"]);
  if (g_big) b.push(["# Datos grandes: deposítalos en Zenodo u otro repositorio y descárgalos con código", "datos/brutos/*.parquet\ndatos/brutos/*.zip"]);
  if (g_quarto) b.push(["# Quarto: salidas generadas", "_site/\n_book/\n/.quarto/\n*_files/"]);
  const txt = b.map(([c, l]) =&gt; c + "\n" + l).join("\n\n");
  const d = html`&lt;div role="status"&gt;&lt;pre&gt;&lt;code&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;`;
  d.querySelector("code").textContent = txt;
  if (g_env) d.append(html`&lt;p class="lab-medio" style="font-weight:600"&gt;Si una clave llega a subirse a GitHub, borrarla del archivo no basta: revócala y genera una nueva.&lt;/p&gt;`);
  return d;
}

Laboratorio: prueba expresiones regulares


Laboratorio · se ejecuta en tu navegador


texto = window.Lab.texto
area = window.Lab.area
viewof patron = texto("Patrón (sintaxis de JavaScript, muy parecida a la de Python)", {value: "10\\.\\d{4,9}/\\S+"})
viewof muestras = area("Textos de prueba (uno por línea)", {rows: 6, value: "https://doi.org/10.1371/journal.pcbi.1005510\nDOI: 10.18637/JSS.V059.I10\ndoi:10.1038/s41586-020-2649-2.\nsin doi\n10.123/corto\nVer 10.1080/00031305.2017.1375986 (2018)"})






























{
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  let re;
  try { re = new RegExp(patron, "i"); } catch (e) { d.innerHTML = `&lt;p class="lab-mal" style="font-weight:600"&gt;Patrón no válido: ${String(e.message).replace(/&lt;/g, "&lt;")}&lt;/p&gt;`; return d; }
  const esc = s =&gt; s.replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  const filas = muestras.split("\n").filter(l =&gt; l.trim()).map(l =&gt; { const m = l.match(re); return `&lt;tr&gt;&lt;td&gt;&lt;code&gt;${esc(l)}&lt;/code&gt;&lt;/td&gt;&lt;td&gt;${m ? `&lt;code&gt;${esc(m[0])}&lt;/code&gt;` : '&lt;span class="lab-mal"&gt;sin coincidencia&lt;/span&gt;'}&lt;/td&gt;&lt;td&gt;${m ? `&lt;code&gt;${esc(m[0].toLowerCase().replace(/[.,;)]+$/, ""))}&lt;/code&gt;` : "—"}&lt;/td&gt;&lt;/tr&gt;`; }).join("");
  d.innerHTML = `&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Texto&lt;/th&gt;&lt;th scope="col"&gt;Coincidencia&lt;/th&gt;&lt;th scope="col"&gt;Normalizado (minúsculas, sin puntuación final)&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;${filas}&lt;/tbody&gt;&lt;/table&gt;
   &lt;p class="small"&gt;Fíjate en el tercer ejemplo: el punto final se cuela en la coincidencia. Por eso conviene quitar la puntuación final al normalizar.&lt;/p&gt;`;
  return d;
}

Laboratorio: consulta OpenAlex en directo


Laboratorio · consulta en directo la API pública de OpenAlex desde tu navegador

Construye la consulta y observa la URL, el número de resultados y los primeros trabajos. Necesita conexión a internet.

texto = window.Lab.texto
rango = window.Lab.rango
casilla = window.Lab.casilla
viewof q_busca = texto("Búsqueda (título, resumen y texto)", {value: "research software", submit: "Consultar"})
viewof q_desde = rango("Desde el año", [2000, 2026], {value: 2020})
viewof q_oa = casilla("Solo acceso abierto", {value: true})












































{
  const filtros = [`from_publication_date:${q_desde}-01-01`, "type:article"].concat(q_oa ? ["is_oa:true"] : []).join(",");
  const url = `https://api.openalex.org/works?search=${encodeURIComponent(q_busca)}&filter=${filtros}&sort=cited_by_count:desc&per_page=5&select=title,publication_year,cited_by_count,doi`;
  const d = html`&lt;div role="status"&gt;&lt;p&gt;&lt;strong&gt;URL:&lt;/strong&gt; &lt;code style="word-break:break-all"&gt;${url}&lt;/code&gt;&lt;/p&gt;&lt;p&gt;Consultando…&lt;/p&gt;&lt;/div&gt;`;
  const esc = s =&gt; String(s ?? "").replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  try {
    const r = await fetch(url);
    const j = await r.json();
    d.lastElementChild.remove();
    d.insertAdjacentHTML("beforeend", `&lt;p&gt;Código de estado &lt;strong&gt;${r.status}&lt;/strong&gt; · &lt;strong&gt;${(j.meta?.count ?? 0).toLocaleString("es-ES")}&lt;/strong&gt; trabajos encontrados. Los cinco más citados:&lt;/p&gt;
      &lt;ol&gt;${(j.results || []).map(w =&gt; `&lt;li&gt;${esc(w.title)} (${w.publication_year}) · ${w.cited_by_count} citas${w.doi ? ` · &lt;a href="${esc(w.doi)}"&gt;${esc(w.doi.replace("https://doi.org/", ""))}&lt;/a&gt;` : ""}&lt;/li&gt;`).join("")}&lt;/ol&gt;
      &lt;p class="small"&gt;Prueba a añadir &lt;code&gt;&amp;group_by=publication_year&lt;/code&gt; a la URL en otra pestaña: OpenAlex devuelve recuentos agregados sin descargar los trabajos.&lt;/p&gt;`);
  } catch (e) {
    d.lastElementChild.outerHTML = '&lt;p class="lab-medio" style="font-weight:600"&gt;No se pudo conectar con OpenAlex (¿sin conexión?). Practica con la muestra guardada en los ejercicios.&lt;/p&gt;';
  }
  return d;
}

Laboratorio: un servidor MCP simulado


Laboratorio · simula los mensajes JSON-RPC de MCP; la herramienta consulta Crossref en directo

Elige el mensaje que envía el cliente y observa la respuesta del servidor bibliometria. La herramienta metadatos_doi consulta de verdad la API de Crossref.

seleccion = window.Lab.seleccion
texto = window.Lab.texto
viewof metodo = seleccion("Mensaje del cliente", ["initialize", "tools/list", "tools/call", "resources/list"], {value: "tools/list"})
viewof arg_doi = texto("Argumento doi (para tools/call)", {value: "10.1371/journal.pcbi.1005510", submit: "Enviar"})






























{
  const herramienta = {name: "metadatos_doi", description: "Devuelve título, revista y año de un DOI consultando Crossref.",
    inputSchema: {type: "object", properties: {doi: {type: "string", description: "DOI sin prefijo de URL"}}, required: ["doi"]}};
  const params = {
    "initialize": {protocolVersion: "2025-06-18", capabilities: {}, clientInfo: {name: "cliente-del-libro", version: "1.0"}},
    "tools/list": {}, "resources/list": {},
    "tools/call": {name: "metadatos_doi", arguments: {doi: arg_doi}}}[metodo];
  const peticion = {jsonrpc: "2.0", id: 1, method: metodo, params};
  let result;
  if (metodo === "initialize") result = {protocolVersion: "2025-06-18", capabilities: {tools: {}, resources: {}}, serverInfo: {name: "bibliometria", version: "0.1.0"}};
  else if (metodo === "tools/list") result = {tools: [herramienta]};
  else if (metodo === "resources/list") result = {resources: [{uri: "datos://publicaciones", name: "publicaciones", mimeType: "text/csv"}]};
  else {
    const doi = (arg_doi || "").trim().toLowerCase().replace(/^https?:\/\/(dx\.)?doi\.org\//, "");
    if (!/^10\.\d{4,9}\/\S+$/.test(doi)) result = {content: [{type: "text", text: "El argumento no parece un DOI válido."}], isError: true};
    else {
      try {
        const r = await fetch(`https://api.crossref.org/works/${encodeURIComponent(doi)}`);
        if (!r.ok) result = {content: [{type: "text", text: `Crossref respondió ${r.status}: DOI no encontrado.`}], isError: true};
        else { const m = (await r.json()).message;
          result = {content: [{type: "text", text: JSON.stringify({titulo: (m.title || [""])[0], revista: (m["container-title"] || [""])[0], anio: m.issued?.["date-parts"]?.[0]?.[0]})}], isError: false}; }
      } catch (e) { result = {content: [{type: "text", text: "Sin conexión con Crossref."}], isError: true}; }
    }
  }
  const respuesta = {jsonrpc: "2.0", id: 1, result};
  const d = html`&lt;div role="status" class="row g-2"&gt;&lt;div class="col-md-6"&gt;&lt;p class="small mb-1"&gt;&lt;strong&gt;Cliente → servidor&lt;/strong&gt;&lt;/p&gt;&lt;pre&gt;&lt;code&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;div class="col-md-6"&gt;&lt;p class="small mb-1"&gt;&lt;strong&gt;Servidor → cliente&lt;/strong&gt;&lt;/p&gt;&lt;pre&gt;&lt;code&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/div&gt;`;
  const [a, b] = d.querySelectorAll("code");
  a.textContent = JSON.stringify(peticion, null, 2); b.textContent = JSON.stringify(respuesta, null, 2);
  return d;
}

3. Un servidor en Python
Con el SDK oficial de Python (rama estable 1.x), la clase FastMCP convierte funciones con anotaciones de tipo y docstring en herramientas, recursos y plantillas:
# servidor.py  ·  ejecutar con: uv run --with "mcp[cli]&lt;2" --with httpx mcp dev servidor.py
import httpx
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("bibliometria")

@mcp.tool()
async def metadatos_doi(doi: str) -&gt; dict:
    """Devuelve título, revista y año de un DOI consultando Crossref."""
    async with httpx.AsyncClient(timeout=20) as cliente:
        r = await cliente.get(f"https://api.crossref.org/works/{doi}")
        r.raise_for_status()
        m = r.json()["message"]
    return {"titulo": m["title"][0],
            "revista": (m.get("container-title") or [""])[0],
            "anio": m["issued"]["date-parts"][0][0]}

@mcp.resource("datos://publicaciones")
def publicaciones() -&gt; str:
    """El CSV de publicaciones del proyecto."""
    with open("datos/publicaciones.csv", encoding="utf-8") as f:
        return f.read()

@mcp.prompt()
def revisar_metadatos(doi: str) -&gt; str:
    """Plantilla para revisar los metadatos de un DOI."""
    return f"Comprueba los metadatos del DOI {doi} con la herramienta metadatos_doi y señala incoherencias."

if __name__ == "__main__":
    mcp.run()            # stdio por defecto; mcp.run(transport="streamable-http") para HTTP
mcp dev abre el MCP Inspector, una interfaz para probar el servidor sin ningún asistente. Para usarlo desde una aplicación compatible se registra en su configuración, normalmente un JSON con el comando que lanza el servidor:
{
  "mcpServers": {
    "bibliometria": {
      "command": "uv",
      "args": ["run", "--with", "mcp[cli]&lt;2", "--with", "httpx", "mcp", "run", "/ruta/a/servidor.py"]
    }
  }
}

Laboratorio · se ejecuta en tu navegador

Las API devuelven JSON anidado: objetos dentro de objetos y listas dentro de registros. Para analizarlo hay que aplanarlo en una tabla. Edita el JSON (tiene la forma de una respuesta de OpenAlex, simplificada) y elige qué hacer con las listas.

areaJ = window.Lab.area
selJ = window.Lab.seleccion
viewof jsonTxt = areaJ("JSON de la respuesta", {rows: 12, value: JSON.stringify({meta: {count: 2}, results: [
  {id: "W1", title: "Open data reuse in libraries", publication_year: 2023, open_access: {is_oa: true, oa_status: "gold"}, authorships: [{author: {display_name: "Ana Ruiz"}}, {author: {display_name: "Luis Gil"}}], concepts: ["Open data", "Libraries"]},
  {id: "W2", title: "Reproducible research software", publication_year: 2024, open_access: {is_oa: false, oa_status: "closed"}, authorships: [{author: {display_name: "Marta Sanz"}}], concepts: ["Software"]}]}, null, 2)})
viewof modoListas = selJ("Listas de objetos (authorships)", ["Unir en una celda con «; »", "Una fila por autor"], {value: "Unir en una celda con «; »"})






























{
  const d = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  const esc = (s) =&gt; String(s).replace(/[&&lt;&gt;]/g, (c) =&gt; ({"&": "&amp;", "&lt;": "&lt;", "&gt;": "&gt;"}[c]));
  let datos;
  try { datos = JSON.parse(jsonTxt); } catch (e) { d.innerHTML = `&lt;p class="text-danger"&gt;⚠ JSON no válido: ${esc(e.message)}. Revisa comas, comillas y llaves.&lt;/p&gt;`; return d; }
  const registros = Array.isArray(datos) ? datos : Array.isArray(datos.results) ? datos.results : [datos];
  const plano = (o, pre = "", out = {}) =&gt; { for (const [k, v] of Object.entries(o)) { const c = pre ? pre + "." + k : k;
    if (v && typeof v === "object" && !Array.isArray(v)) plano(v, c, out);
    else if (Array.isArray(v)) out[c] = v.map((x) =&gt; x && typeof x === "object" ? Object.values(plano(x)).join(" ") : x).join("; ");
    else out[c] = v; } return out; };
  let filas = [];
  if (modoListas.startsWith("Una fila")) registros.forEach((r) =&gt; { const {authorships = [], ...resto} = r; const base = plano(resto); (authorships.length ? authorships : [{}]).forEach((a) =&gt; filas.push({...base, ...plano(a, "authorships")})); });
  else filas = registros.map((r) =&gt; plano(r));
  const cols = [...new Set(filas.flatMap(Object.keys))];
  const r = `library(jsonlite)\nrespuesta &lt;- fromJSON("respuesta.json", flatten = TRUE)\ntabla &lt;- respuesta$results${modoListas.startsWith("Una fila") ? "\n# una fila por autor\ntabla &lt;- tidyr::unnest(tabla, authorships)" : "\n# listas a texto\ntabla$authorships &lt;- vapply(tabla$authorships, function(a) paste(a$author.display_name, collapse = \"; \"), \"\")"}`;
  const py = `import json\nimport pandas as pd\n\nwith open("respuesta.json") as f:\n    datos = json.load(f)\n${modoListas.startsWith("Una fila") ? 'tabla = pd.json_normalize(datos["results"], record_path="authorships",\n                          meta=["id", "title", "publication_year"], sep=".")' : 'tabla = pd.json_normalize(datos["results"], sep=".")'}`;
  d.innerHTML = `&lt;p&gt;&lt;strong&gt;${filas.length} filas × ${cols.length} columnas&lt;/strong&gt;&lt;/p&gt;&lt;div class="table-responsive"&gt;&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;${cols.map((c) =&gt; `&lt;th scope="col"&gt;&lt;code&gt;${esc(c)}&lt;/code&gt;&lt;/th&gt;`).join("")}&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;${filas.map((f) =&gt; `&lt;tr&gt;${cols.map((c) =&gt; `&lt;td&gt;${f[c] === undefined ? "&lt;em&gt;NA&lt;/em&gt;" : esc(f[c])}&lt;/td&gt;`).join("")}&lt;/tr&gt;`).join("")}&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;
  &lt;div class="row"&gt;&lt;div class="col-md-6"&gt;&lt;p class="small mb-1"&gt;En R&lt;/p&gt;&lt;pre class="sourceCode"&gt;&lt;code&gt;${esc(r)}&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;div class="col-md-6"&gt;&lt;p class="small mb-1"&gt;En Python&lt;/p&gt;&lt;pre class="sourceCode"&gt;&lt;code&gt;${esc(py)}&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/div&gt;`;
  return d;
}






Fíjate en que «una fila por autor» multiplica las filas: si después cuentas artículos, cuenta valores distintos de id, no filas.
